import { path } from '@servicenow/sdk-build-core'
import { findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from './test-utils'
import { createTestContext } from '../../test-utils'

describe('Record Trigger Types Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Created record trigger with conditions', () => {
        test('Incident created trigger instance with conditions maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'created-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(3)

            // Get the first flow (testCreatedTrigger)
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('active=true')
            expect(val('run_on_extended')).toBe('false')
            expect(val('run_flow_in')).toBe('background')
            expect(val('run_when_setting')).toBe('both')
            expect(val('run_when_user_setting')).toBe('any')
        })

        test('Created trigger with mandatory fields only (DEF0777644)', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'created-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(3)

            // Get the second flow (testCreatedTriggerMandatoryOnly)
            const trgInst = merged['sys_hub_trigger_instance_v2'][1]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Only table is specified, all others should use defaults
            expect(val('table')).toBe('incident')
        })

        test('Created trigger with non-default parameters', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'created-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(3)

            // Get the third flow (testCreatedTriggerWithNonDefaultParams)
            const trgInst = merged['sys_hub_trigger_instance_v2'][2]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('active=true^short_descriptionSTARTSWITHOutage')
            expect(val('run_on_extended')).toBe('true')
            expect(val('run_flow_in')).toBe('foreground')
            expect(val('run_when_setting')).toBe('non_interactive')
            expect(val('run_when_user_setting')).toBe('one_of')
        })
    })

    describe('Updated record trigger with conditions', () => {
        test('Incident update trigger instance with conditions maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'updated-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            // Get the first flow (testUpdatedTrigger)
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('state!=7')
            expect(val('run_on_extended')).toBe('false')
            expect(val('run_flow_in')).toBe('background')
            expect(val('run_when_setting')).toBe('both')
            expect(val('run_when_user_setting')).toBe('any')
            expect(val('trigger_strategy')).toBe('unique_changes')
        })

        test('Updated trigger with non-default parameters', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'updated-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            // Get the second flow (testUpdatedTriggerOnlyMandatory)
            const trgInst = merged['sys_hub_trigger_instance_v2'][1]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('active=true^short_descriptionSTARTSWITHOutage')
            expect(val('run_on_extended')).toBe('true')
            expect(val('run_flow_in')).toBe('foreground')
            expect(val('run_when_setting')).toBe('non_interactive')
            expect(val('run_when_user_setting')).toBe('one_of')
            expect(val('trigger_strategy')).toBe('once')
        })
    })

    describe('Created or Updated record trigger', () => {
        test('Incident create-or-update trigger instance maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'created-or-updated-trigger.now.ts',
                'oob-triggers/fluent'
            )

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            // Get the first flow (testCreatedOrUpdatedTrigger)
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('priority<=2')
            expect(val('run_on_extended')).toBe('false')
            expect(val('run_flow_in')).toBe('background')
            expect(val('run_when_setting')).toBe('both')
            expect(val('run_when_user_setting')).toBe('any')
            expect(val('trigger_strategy')).toBe('unique_changes')
        })

        test('Created or Updated trigger with non-default parameters', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'created-or-updated-trigger.now.ts',
                'oob-triggers/fluent'
            )

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            // Get the second flow (testCreatedOrUpdatedTriggerOnlyMandatory)
            const trgInst = merged['sys_hub_trigger_instance_v2'][1]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            // No condition specified in this flow
            expect(val('run_on_extended')).toBe('true')
            expect(val('run_flow_in')).toBe('foreground')
            expect(val('run_when_setting')).toBe('non_interactive')
            expect(val('run_when_user_setting')).toBe('one_of')
            expect(val('trigger_strategy')).toBe('always')
        })
    })

    // =============================================================================
    // Bi-Directional Tests: Fluent → XML → Fluent
    // =============================================================================

    describe('Record Triggers - Fluent to XML', () => {
        test('Created trigger generates correct XML with all parameters', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'created-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(3)

            // Verify first flow (testCreatedTrigger)
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('record_create')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('active=true')
            expect(val('run_on_extended')).toBe('false')
            expect(val('run_flow_in')).toBe('background')
            expect(val('run_when_setting')).toBe('both')
            expect(val('run_when_user_setting')).toBe('any')
        })

        test('Updated trigger generates correct XML with trigger_strategy', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'updated-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('record_update')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('state!=7')
            expect(val('trigger_strategy')).toBe('unique_changes')
        })

        test('Created-or-Updated trigger generates correct XML', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'created-or-updated-trigger.now.ts',
                'oob-triggers/fluent'
            )

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            expect(trgInst.trigger_type).toBe('record_create_or_update')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('priority<=2')
            expect(val('trigger_strategy')).toBe('unique_changes')
        })
    })

    describe('Record Triggers - XML to Fluent', () => {
        test('Created trigger XML transforms with all parameters validated', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Created_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Created_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.record.created')
            expect(content).toContain('Flow(')
            expect(content).toContain('wfa.trigger(')

            // Verify trigger parameters with actual values
            expect(content).toContain("table: 'incident'")
            expect(content).toContain("condition: 'active=true'")
            // TODO DEF0785364: XML-to-Fluent generates boolean fields as strings ('true'/'false')
            expect(content).toContain("run_on_extended: 'false'")
            expect(content).toContain("run_flow_in: 'background'")
            expect(content).toContain("run_when_setting: 'both'")
            expect(content).toContain("run_when_user_setting: 'any'")
        })

        test('Created trigger with non-default params validates all parameters', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(project, 'created-trigger.now.ts', 'oob-triggers/fluent')

            // Get the first flow which has non-default parameters
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('record_create')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify trigger parameters with precise values
            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('active=true')
            expect(val('run_on_extended')).toBe('false')
            expect(val('run_flow_in')).toBe('background')
            expect(val('run_when_setting')).toBe('both')
            expect(val('run_when_user_setting')).toBe('any')
        })

        test('Created trigger mandatory only validates only table parameter', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Created_Trigger_Mandatory_Only.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Created_Trigger_Mandatory_Only.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.record.created')

            // Verify only mandatory parameter (table)
            expect(content).toContain("table: 'incident'")
        })

        test('Created trigger with non-default parameters XML transforms correctly', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Created_Non_Default_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Created_Non_Default_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            expect(changedFiles[0].getName()).toBe('Test_Created_Non_Default_Trigger.now.ts')

            const content = changedFiles[0].getContent()

            // Verify trigger type
            expect(content).toContain('trigger.record.created')
            expect(content).toContain('wfa.trigger(')

            // Verify table parameter
            expect(content).toContain("table: 'incident'")

            // Verify non-default parameters are present
            expect(content).toMatch(/condition:|run_on_extended:|run_flow_in:|run_when_setting:|run_when_user_setting:/)

            // Verify trigger outputs are accessible
            expect(content).toContain('_params.trigger')
        })

        test('Updated trigger XML validates all parameters including trigger_strategy', async () => {
            const project = ctx.createProject()

            // Use the existing Fluent file for precise validation
            const merged = await getMergedRecordUpdates(project, 'updated-trigger.now.ts', 'oob-triggers/fluent')

            // Get the first flow
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]

            // Verify trigger type
            expect(trgInst.trigger_type).toBe('record_update')

            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify trigger parameters with precise values including trigger_strategy
            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('state!=7')
            expect(val('trigger_strategy')).toBe('unique_changes')
        })

        test('Updated trigger mandatory only validates only table parameter', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Updated_Trigger_Mandatory_Only.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Updated_Trigger_Mandatory_Only.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.record.updated')

            // Verify only mandatory parameter (table)
            expect(content).toContain("table: 'incident'")
        })

        test('Created-or-Updated trigger XML validates all parameters', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Created_Updated_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Created_Updated_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.record.createdOrUpdated')
            expect(content).toContain('params.trigger')

            // Verify trigger parameters with actual values
            expect(content).toContain("table: 'incident'")
            expect(content).toContain("condition: 'priority<=2'")
            expect(content).toContain("trigger_strategy: 'unique_changes'")
            // TODO DEF0785364: XML-to-Fluent generates boolean fields as strings ('true'/'false')
            expect(content).toContain("run_on_extended: 'false'")
        })

        test('Created-or-Updated trigger mandatory only validates only table parameter', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Created_Updated_Trigger_Mandatory_Only.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Created_Updated_Trigger_Mandatory_Only.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.record.createdOrUpdated')

            // Verify only mandatory parameter (table)
            expect(content).toContain("table: 'incident'")
        })

        test('Created trigger XML transforms to correct Fluent code', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Created_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Created_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.record.created')
            expect(content).toContain('Flow(')
            expect(content).toContain('wfa.trigger(')

            // Verify trigger parameters with actual values
            expect(content).toContain("table: 'incident'")
            expect(content).toContain("condition: 'active=true'")

            // Verify trigger outputs are accessible
            expect(content).toContain('params.trigger.current')
            expect(content).toContain('params.trigger.table_name')
        })

        test('Updated trigger XML transforms with changed_fields output', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Updated_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Updated_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.record.updated')

            // Verify trigger parameters with actual values
            expect(content).toContain("table: 'incident'")
            expect(content).toContain("condition: 'state!=7'")
            expect(content).toContain("trigger_strategy: 'unique_changes'")

            // Verify trigger outputs are accessible including changed_fields
            expect(content).toContain('params.trigger.current')
            expect(content).toContain('params.trigger.table_name')
            expect(content).toContain('params.trigger.changed_fields')
        })

        test('Created-or-Updated trigger XML transforms with all parameters', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Created_Updated_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Created_Updated_Trigger.xml',
                content: xmlContent,
            })

            expect(changedFiles.length).toBe(1)
            const content = changedFiles[0].getContent()

            // Verify trigger type in generated code
            expect(content).toContain('trigger.record.createdOrUpdated')

            // Verify trigger parameters with actual values
            expect(content).toContain("table: 'incident'")
            expect(content).toContain("condition: 'priority<=2'")
            expect(content).toContain("trigger_strategy: 'unique_changes'")

            // Verify trigger outputs are accessible
            expect(content).toContain('params.trigger.current')
            expect(content).toContain('params.trigger.table_name')
            expect(content).toContain('params.trigger.changed_fields')

            // Verify correct data types are used for data pills
            expect(content).toContain("wfa.dataPill(_params.trigger.current, 'reference')")
            expect(content).toContain("wfa.dataPill(_params.trigger.table_name, 'table_name')")
            //expect(content).toContain("wfa.dataPill(_params.trigger.changed_fields, 'array.object')")
            expect(content).toContain("wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')")
        })

        test('Created trigger Fluent code uses all trigger outputs including run_start_time', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('Test_Created_Trigger.xml', 'oob-triggers/xml')
            const { changedFiles } = await project.transform({
                path: 'Test_Created_Trigger.xml',
                content: xmlContent,
            })

            const content = changedFiles[0].getContent()

            // Verify all trigger outputs are used in log messages
            expect(content).toContain('_params.trigger.current')
            expect(content).toContain('_params.trigger.table_name')
            expect(content).toContain('_params.trigger.run_start_date_time')
            expect(content).toContain('_params.trigger.current.assignment_group')
            expect(content).toContain('_params.trigger.current.assignment_group.description')

            // Verify correct data types are used for data pills
            expect(content).toContain("wfa.dataPill(_params.trigger.current, 'reference')")
            expect(content).toContain("wfa.dataPill(_params.trigger.table_name, 'table_name')")
            expect(content).toContain("wfa.dataPill(_params.trigger.run_start_date_time, 'glide_date_time')")
            expect(content).toContain("wfa.dataPill(_params.trigger.current.assignment_group, 'reference')")
            expect(content).toContain("wfa.dataPill(_params.trigger.current.assignment_group.description, 'string')")
        })
    })

    describe('Record Triggers - Round Trip', () => {
        test('Created trigger: Fluent → XML preserves all configurations', async () => {
            const project = ctx.createProject()

            const merged = await getMergedRecordUpdates(project, 'created-trigger.now.ts', 'oob-triggers/fluent')

            // Verify all 3 flows are generated
            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(3)

            // Verify each flow has correct trigger_type
            merged['sys_hub_trigger_instance_v2'].forEach((trgInst: any) => {
                expect(trgInst.trigger_type).toBe('record_create')
            })
        })

        test('Updated trigger: Fluent → XML preserves trigger_strategy', async () => {
            const project = ctx.createProject()

            const merged = await getMergedRecordUpdates(project, 'updated-trigger.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify trigger_strategy is preserved
            expect(val('trigger_strategy')).toBe('unique_changes')
            expect(val('table')).toBe('incident')
        })

        test('Created-or-Updated trigger: Fluent → XML preserves all parameters', async () => {
            const project = ctx.createProject()

            const merged = await getMergedRecordUpdates(
                project,
                'created-or-updated-trigger.now.ts',
                'oob-triggers/fluent'
            )

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(2)

            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Verify all parameters are preserved
            expect(val('table')).toBeDefined()
            expect(val('condition')).toBeDefined()
            expect(val('trigger_strategy')).toBeDefined()
            expect(val('run_on_extended')).toBeDefined()
        })
    })
})
